'use strict';
const $=id=>document.getElementById(id),args=new URLSearchParams(location.hash.slice(1));let receiver,pair,expected;
async function api(route,data){const r=await fetch(route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(15000)}),v=await r.json();if(!r.ok)throw Error(v.error||'Không xác nhận được phiên.');return v}
async function bridge(route,data){const r=await fetch(receiver+route,{method:data?'POST':'GET',headers:{'X-Mizze-Pair':pair,...(data?{'Content-Type':'application/json'}:{})},...(data?{body:JSON.stringify(data)}:{}),mode:'cors',credentials:'omit',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(15000)}),v=await r.json();if(!r.ok)throw Error(v.error||'Không kết nối được bộ ghi.');return v}
(async()=>{try{const url=new URL(args.get('receiver'));pair=args.get('pair');if(url.protocol!=='https:'||!url.hostname.endsWith('.trycloudflare.com')||url.username||url.password||url.pathname!=='/'||url.search||url.hash||!/^[a-f0-9]{64}$/.test(pair||''))throw Error('Liên kết ghép không hợp lệ. Mở đúng liên kết được tạo trên PC.');receiver=url.origin;expected=await bridge('/pair-info');$('key-label').textContent=expected.keyLabel;$('badge').textContent=expected.paired?'Đã ghép phiên này':'Đã kết nối bộ ghi PC';$('status').textContent=expected.paired?'Phiên đã ghép. Bạn có thể trở lại game và làm theo bảng PC.':'Nhập key để xác nhận đúng phiên trên trình duyệt này.';$('pair').disabled=expected.paired;if(expected.paired)$('pair-form').hidden=true;}catch(e){$('status').textContent=e.message;$('badge').textContent='Chưa ghép'}})();
$('pair-form').onsubmit=async event=>{event.preventDefault();$('pair').disabled=true;try{const key=$('key').value.trim().toUpperCase(),deviceId=localStorage.getItem('mizze-device');if(!/^[a-f0-9]{32}$/.test(deviceId||''))throw Error('Hãy mở liên kết trên đúng trình duyệt đã thêm cấu hình Happ.');const keyHash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(key))),b=>b.toString(16).padStart(2,'0')).join('');if(keyHash!==expected.keyHash)throw Error('Key này không khớp phiên đo được tạo trên PC.');$('status').textContent='Đang xác nhận key và phiên đang có…';const login=await api('/api/login',{key,deviceId});$('key').value='';await bridge('/pair',{keyHash,grant:login.grant});$('pair-form').hidden=true;$('badge').textContent='Đã ghép thành công';$('status').textContent='PC đang đọc thống kê của riêng phiên này. Bạn chuyển về game, chờ bảng PC báo lượt bắt đầu rồi làm theo hướng dẫn.';}catch(e){$('status').textContent=e.message;$('pair').disabled=false}};
